internal data class PrivacySafetyCopy(
    val title: String,
    val sections: List<PrivacySafetySectionCopy>,
)

internal data class PrivacySafetySectionCopy(
    val title: String,
    val body: String,
)

internal fun privacyPolicyCopy(language: AppLanguage): PrivacySafetyCopy {
    val title = when (language) {
        AppLanguage.Polish -> "Polityka prywatności"
        AppLanguage.Slovak -> "Zásady ochrany súkromia"
        AppLanguage.Czech -> "Zásady ochrany osobních údajů"
        AppLanguage.German -> "Datenschutzerklärung"
        AppLanguage.French -> "Politique de confidentialité"
        AppLanguage.Spanish -> "Política de privacidad"
        AppLanguage.Portuguese -> "Política de privacidade"
        AppLanguage.Italian -> "Informativa sulla privacy"
        AppLanguage.Dutch -> "Privacybeleid"
        AppLanguage.Danish -> "Privatlivspolitik"
        AppLanguage.Swedish -> "Integritetspolicy"
        AppLanguage.Norwegian -> "Personvern"
        AppLanguage.Estonian -> "Privaatsuspoliitika"
        AppLanguage.Latvian -> "Privātuma politika"
        AppLanguage.Lithuanian -> "Privatumo politika"
        AppLanguage.Hungarian -> "Adatvédelmi szabályzat"
        AppLanguage.Greek -> "Πολιτική απορρήτου"
        AppLanguage.Russian -> "Политика конфиденциальности"
        AppLanguage.Ukrainian -> "Політика конфіденційності"
        AppLanguage.Serbian -> "Политика приватности"
        AppLanguage.Croatian -> "Pravila privatnosti"
        AppLanguage.Macedonian -> "Политика за приватност"
        AppLanguage.Albanian -> "Politika e privatësisë"
        AppLanguage.Hindi -> "गोपनीयता नीति"
        AppLanguage.Bengali -> "গোপনীয়তা নীতি"
        AppLanguage.Urdu -> "رازداری کی پالیسی"
        AppLanguage.ChineseSimplified -> "隐私政策"
        AppLanguage.Japanese -> "プライバシーポリシー"
        AppLanguage.Korean -> "개인정보 처리방침"
        AppLanguage.Thai -> "นโยบายความเป็นส่วนตัว"
        AppLanguage.Malay -> "Dasar privasi"
        AppLanguage.Latin -> "Consilium de secreto"
        AppLanguage.English -> "Privacy policy"
    }
    return PrivacySafetyCopy(
        title = title,
        sections = privacyPolicySections(language),
    )
}

private fun privacyPolicySections(language: AppLanguage): List<PrivacySafetySectionCopy> {
    fun section(title: String, body: String) = PrivacySafetySectionCopy(title, body)
    return when (language) {
        AppLanguage.Albanian -> listOf(
            section("Përmbledhje", "Elovaire është një luajtës lokal muzike i shpërndarë përmes GitHub. Nuk kërkon llogari, profil reklamash, analitikë ose bibliotekë muzikore në renë kompjuterike."),
            section("Skedarët muzikorë dhe media", "Elovaire lexon skedarët audio, etiketat, kopertinat dhe tekstet e këngëve vetëm në dosjet ose dokumentet për të cilat i jepni leje. Ndryshimet e etiketave dhe teksteve bëhen vetëm pasi i kërkoni dhe Android lejon shkrimin. Skedarët audio të plotë nuk ngarkohen."),
            section("Shërbimet opsionale online", "Kur aktivizohet ose nevojitet për një veçori të kërkuar, Elovaire mund t'u dërgojë LRCLIB, YouTube Music ose Google Books të dhëna të kufizuara për këngën, artistin ose librin audio. Këto shërbime nuk marrin skedarët tuaj audio; zbatohen politikat e tyre të privatësisë. Çaktivizoni veçoritë online për t'i ndaluar këto kërkesa."),
            section("Të dhënat lokale të aplikacionit", "Listat e dëgjimit, përzierjet inteligjente, të preferuarat, historiku dhe numërimi i dëgjimit, historiku i kërkimit, cilësimet, indeksi i bibliotekës, memoriet e kopertinave dhe metadatave dhe preferencat e përditësimeve qëndrojnë në pajisje. Rezervimi i Android mund të përfshijë cilësime të transportueshme; skedarët muzikorë, lejet, memoriet dhe regjistrat e veprimeve përjashtohen."),
            section("Dosjet në rrjet dhe lejet", "Elovaire mund të kërkojë qasje te mediat audio, njoftime për riprodhimin, qasje te dokumentet për dosjet që zgjidhni, qasje në rrjetin lokal për burimet SMB/WebDAV, qasje USB për pajisjet audio të pajtueshme dhe leje për instalimin e përditësimeve nga GitHub. Çdo leje përdoret vetëm për veçorinë përkatëse."),
            section("Rrjeti", "Përveç veçorive opsionale online dhe përditësimeve nga GitHub, aplikacioni nuk ka nevojë për lidhje rrjeti. Elovaire nuk dërgon përmbajtje muzikore, lista dëgjimi ose historik kërkimi te serverët e tij."),
            section("Përditësimet nga GitHub", "Përditësuesi vetëm nga GitHub kontrollon publikimet dhe shkarkon një APK dhe shumën e kontrollit kur kërkoni përditësim ose kur duhet një kontroll automatik në plan të parë. GitHub merr informacion normal të kërkesës, si adresa juaj IP. Elovaire verifikon shumën e kontrollit, emrin e paketës, versionin dhe certifikatën e nënshkrimit përpara se Android të kërkohet të instalojë përditësimin."),
            section("Ndarja, ruajtja dhe fshirja", "Elovaire nuk shet ose ndan të dhënat tuaja lokale muzikore. Të dhënat lokale qëndrojnë derisa të pastroni të dhënat e aplikacionit, t'i hiqni përmes një veçorie të aplikacionit ose ta çinstaloni atë. Skedarët e përkohshëm të përditësimit pastrohen kur nuk nevojiten më. Kodi burimor dhe APK-të e publikimit gjenden në github.com/droidbeauty/elovaire-music."),
        )
        AppLanguage.Bengali -> listOf(
            section("সংক্ষিপ্ত বিবরণ", "Elovaire GitHub-এর মাধ্যমে বিতরণ করা একটি স্থানীয় মিউজিক প্লেয়ার। এতে অ্যাকাউন্ট, বিজ্ঞাপন প্রোফাইল, বিশ্লেষণ বা ক্লাউড মিউজিক লাইব্রেরি প্রয়োজন হয় না।"),
            section("মিউজিক ও মিডিয়া ফাইল", "আপনি যে ফোল্ডার বা নথির অনুমতি দেন, Elovaire শুধু সেখানকার অডিও ফাইল, ট্যাগ, প্রচ্ছদ ও গানের কথা পড়ে। আপনি অনুরোধ করার পর এবং Android লেখার অনুমতি দিলে তবেই ট্যাগ বা গানের কথা সম্পাদনা হয়। সম্পূর্ণ অডিও ফাইল আপলোড করা হয় না।"),
            section("ঐচ্ছিক অনলাইন পরিষেবা", "কোনও অনলাইন সুবিধা চালু থাকলে বা অনুরোধ করা সুবিধার জন্য প্রয়োজন হলে, Elovaire গানের কথা, শিল্পীর ছবি বা অডিওবুকের বিবরণ আনতে LRCLIB, YouTube Music বা Google Books-এ সীমিত গান, শিল্পী বা বইয়ের মেটাডেটা পাঠাতে পারে। এই পরিষেবাগুলি আপনার অডিও ফাইল পায় না; তাদের নিজস্ব গোপনীয়তা নীতি প্রযোজ্য। এই অনুরোধ বন্ধ করতে অনলাইন সুবিধা নিষ্ক্রিয় করুন।"),
