            section("Overview", "Elovaire is a local music player distributed through GitHub. It does not require an account, advertising profile, analytics, or a cloud music library."),
            section("Music and media files", "Elovaire reads audio files, tags, artwork, and lyrics only in folders or documents that you grant it access to. Tag and lyric edits happen only after you request them and Android allows writing. Complete audio files are never uploaded."),
            section("Optional online services", "When enabled or needed for a requested feature, Elovaire may send limited song, artist, or book metadata to LRCLIB, YouTube Music, or Google Books to retrieve lyrics, artist images, or audiobook descriptions. These services do not receive your audio files; their own privacy policies apply. Disable online features to prevent these requests."),
            section("Local app data", "Playlists, smart mixes, favorites, play history, play counts, search history, settings, the library index, artwork and metadata caches, and update preferences remain on the device. Android backup may include portable settings; music files, permissions, caches, and operation journals are excluded."),
            section("Network folders and permissions", "Elovaire may request audio-media access, playback notifications, document access for folders you choose, local-network access for SMB/WebDAV sources, USB access for compatible audio devices, and permission to install GitHub updates. Each permission is used only for the related feature."),
            section("Network", "Except for optional online features and GitHub updates, the app does not need a network connection. Elovaire does not send music content, playlists, or search history to its servers."),
            section("GitHub updates", "The GitHub-only updater checks public releases and downloads an APK and its checksum when you check for an update or an automatic foreground check is due. GitHub receives normal request information such as your IP address. Elovaire verifies the checksum, package name, version, and signing certificate before asking Android to install an update."),
            section("Sharing, retention, and deletion", "Elovaire does not sell or share your local music data. Local data remains until you clear app data, remove it through an in-app feature, or uninstall the app. Temporary update files are cleaned when they are no longer needed. The source code and release APKs are published at github.com/droidbeauty/elovaire-music."),
        )
    }
}

